/**
 * The ways in: a compact card for an account whose notebooks are still small
 * (owner, 2026-10-17; reworked for the first visit to Today, uiux
 * 2026-10-22-today-first-visit M3, owner-approved 22 Oct 2026).
 *
 * With words it is "Save words where you meet them": the routes for the
 * places the learner said they meet words in onboarding (`waysFor`), each with
 * the product's own mark. With an empty notebook it is "Or bring in words you
 * already have", the deck import first. It replaced both "More ways to bring
 * in words" and the getting-started chip in Today's corner, which said the
 * same thing twice. It sits below the day's plan, never above it, until the
 * notebook has grown or the learner puts it away.
 *
 * While the notebook holds one to four words it is the first-five card (uiux
 * 2026-10-26-activation; growth audit: half of new accounts stop there): the
 * goal of five as a meter and a count, what to do in one line, and the ways
 * in other than typing (`firstFiveWays`), pasting a text first. It counts
 * only the learner's own words and names none. At five it becomes "Save words
 * where you meet them" in place; the same × puts every variant away.
 */
import { useId } from 'react';
import { Link } from 'react-router-dom';
import { Icon } from '@/components/ui/Icon.js';
import { cx } from '@/lib/cx.js';
import { db, getMeta, setMeta, type MetaShape } from '@/db/schema.js';
import { CONNECT_ASSISTANT_PATH } from '@/features/settings/connectAssistant.js';
import { settingsPath } from '@/features/settings/paths.js';
import { plural, t, type MessageKey } from '@/i18n/index.js';
import { DEFAULT_ACCELERATOR, prettyShortcut } from '@/lib/desktopShortcut.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { currentDevice } from '@/lib/platform/device.js';
import { FIRST_FIVE_GOAL, isFirstFive, offersWaysIn } from './offer.js';
import { WayMark } from './WayMark.js';
import { firstFiveWays, waysFor, type WayId } from './ways.js';
import styles from './WaysIn.module.css';

/** Each way, to the screen that already does it. */
const WAYS: Readonly<Record<Exclude<WayId, 'paste'>, { to: string; title: MessageKey; line: MessageKey }>> = {
  import: { to: settingsPath('data'), title: 'waysIn.importTitle', line: 'waysIn.importLine' },
  kindle: { to: settingsPath('data'), title: 'waysIn.kindleTitle', line: 'waysIn.kindleLine' },
  web: { to: settingsPath('everywhere'), title: 'waysIn.webTitle', line: 'waysIn.webLine' },
  watch: { to: settingsPath('everywhere'), title: 'waysIn.watchTitle', line: 'waysIn.watchLine' },
  list: { to: '/ai', title: 'waysIn.listTitle', line: 'waysIn.listLine' },
  assistants: {
    to: CONNECT_ASSISTANT_PATH,
    title: 'waysIn.assistantsTitle',
    line: 'waysIn.assistantsLine',
  },
};

/**
 * Where a computer has room for the extension and the desktop shortcut: a
 * browser that is not a phone's or tablet's, or the desktop app.
 */
function onComputer(): boolean {
  const device = currentDevice();
  return !device.mobile && (device.shell === 'web' || device.shell === 'desktop');
}

/**
 * The card, or nothing once the notebook has grown or it was put away.
 * `onPaste` opens the screen's Paste a text sheet; without it there is no
 * paste row.
 */
export function WaysIn({
  words,
  onPaste,
}: {
  words: number;
  onPaste?: (() => void) | undefined;
}): React.JSX.Element | null {
  const pasteTitleId = useId();
  const pasteLineId = useId();
  // Undefined until read, so a learner who put it away never sees it flash.
  const dismissed = useLiveQuery<boolean | undefined>(() => getMeta('waysInDismissed'), undefined, []);
  // Undefined until read too: drawn with the default routes first, the card
  // reordered itself under the reader a frame later.
  const sources = useLiveQuery<MetaShape['wordSources'] | undefined>(
    () => getMeta('wordSources'),
    undefined,
    [],
  );
  // Every word of the account, in every notebook: the goal is the account's
  // first five, never a new notebook's. Undefined until read, so the card
  // never draws one variant and swaps to the other a frame later.
  const accountWords = useLiveQuery<number | undefined>(() => db.words.count(), undefined, []);
  if (
    dismissed === undefined ||
    sources === undefined ||
    accountWords === undefined ||
    !offersWaysIn(words, dismissed)
  ) {
    return null;
  }
  // The account's count, which is never below this notebook's (a word just
  // saved may reach this screen's count before the live read).
  const counted = Math.max(words, accountWords);
  const first = isFirstFive(words, counted);
  const ways = first
    ? firstFiveWays(sources, onComputer()).filter((id) => id !== 'paste' || onPaste !== undefined)
    : waysFor(words, sources);
  const left = FIRST_FIVE_GOAL - counted;
  return (
    <section className={styles.card} aria-labelledby="ways-in-title">
      <div className={styles.head}>
        <h2 id="ways-in-title" className={styles.title}>
          {t(first ? 'firstFive.title' : words === 0 ? 'waysIn.titleEmpty' : 'waysIn.title', {
            goal: FIRST_FIVE_GOAL,
          })}
        </h2>
        <button
          type="button"
          className={styles.close}
          aria-label={t('waysIn.hide')}
          onClick={() => {
            void setMeta('waysInDismissed', true);
          }}
        >
          <Icon name="close" size={16} weight={2} />
        </button>
      </div>
      {first && (
        <>
          <div className={styles.progress}>
            <span className={styles.meter} aria-hidden="true">
              {Array.from({ length: FIRST_FIVE_GOAL }, (_, index) => (
                <span key={index} className={cx(styles.step, index < counted && styles.filled)} />
              ))}
            </span>
            <p className={styles.count}>{t('firstFive.count', { n: counted, goal: FIRST_FIVE_GOAL })}</p>
          </div>
          <p className={styles.lead}>{plural(left, 'firstFive.leadOne', 'firstFive.lead')}</p>
        </>
      )}
      <ul className={styles.list}>
        {ways.map((id) => (
          <li key={id}>
            {id === 'paste' ? (
              <button
                type="button"
                className={cx(styles.row, styles.rowButton)}
                aria-labelledby={pasteTitleId}
                aria-describedby={pasteLineId}
                onClick={onPaste}
              >
                <WayMark way={id} />
                <span className={styles.text}>
                  <span id={pasteTitleId} className={styles.rowTitle}>
                    {t('waysIn.pasteTitle')}
                  </span>
                  <span id={pasteLineId} className={styles.line}>
                    {t('waysIn.pasteLine')}
                  </span>
                </span>
                <Icon name="chevronRight" size={16} weight={2} className={styles.chevron} />
              </button>
            ) : (
              <Link to={WAYS[id].to} className={styles.row}>
                <WayMark way={id} />
                <span className={styles.text}>
                  <span className={styles.rowTitle}>{t(WAYS[id].title)}</span>
                  <span className={styles.line}>{lineOf(id)}</span>
                </span>
                <Icon name="chevronRight" size={16} weight={2} className={styles.chevron} />
              </Link>
            )}
          </li>
        ))}
      </ul>
    </section>
  );
}

/** A way's line; the desktop shortcut is said as the keys this device's app uses. */
function lineOf(id: Exclude<WayId, 'paste'>): React.ReactNode {
  if (id !== 'watch') return t(WAYS[id].line);
  const [before = '', middle = '', after = ''] = t('waysIn.watchLine', { mac: '\u0000', pc: '\u0000' }).split(
    '\u0000',
  );
  return (
    <>
      {before}
      <kbd className={styles.kbd}>{prettyShortcut(DEFAULT_ACCELERATOR, true)}</kbd>
      {middle}
      <kbd className={styles.kbd}>{prettyShortcut(DEFAULT_ACCELERATOR, false)}</kbd>
      {after}
    </>
  );
}
