/** When the "More ways to bring in words" card is offered (WaysIn.tsx). */

/**
 * Below this many words the card is offered. A product threshold about what
 * "still small" means for a notebook, not a limit or a tunable the server
 * owns: past it the learner has clearly found a way in that works for them.
 */
export const WAYS_IN_MAX_WORDS = 10;

/** Whether the card is for this many words. Pure, for the screens and tests. */
export function offersWaysIn(words: number, dismissed: boolean): boolean {
  return !dismissed && words < WAYS_IN_MAX_WORDS;
}

/**
 * The first goal a new notebook is shown (growth audit 2026-10-26: 86% of new
 * accounts add a word, 36% reach five, half stop at one to four). A product
 * definition of "a notebook that has started", not a limit and not a server
 * tunable: nothing in the app changes at five, it is only the near goal the
 * card counts towards, and the card goes once it is reached.
 */
export const FIRST_FIVE_GOAL = 5;

/**
 * Whether the ways-in card is the first-five card: the notebook in view has a
 * word, and the whole account, every notebook together, has fewer than five.
 * A learner with five words anywhere who starts a new notebook is not new and
 * keeps "Save words where you meet them" (code review, 27 Oct 2026).
 */
export function isFirstFive(words: number, accountWords: number): boolean {
  return words >= 1 && accountWords < FIRST_FIVE_GOAL;
}
