/**
 * Which ways in Today's card names, and in what order (uiux
 * 2026-10-22-today-first-visit M3, owner-approved 22 Oct 2026; onboarding v2
 * spec §4.5 for the answers, meta `wordSources`).
 *
 * With words in the notebook the card is "Save words where you meet them":
 * the routes for the places the learner said they meet words, in the order
 * they ticked them, at most three. With an empty notebook it is "Or bring in
 * words you already have", and the deck import from Anki, Quizlet or a sheet
 * comes first, because that is when a learner who has a list wants it.
 */
import type { MetaShape } from '@/db/schema.js';

export type WayId = 'import' | 'kindle' | 'web' | 'watch' | 'list' | 'assistants' | 'paste';

type Source = MetaShape['wordSources'][number];

/** Where each answer to "Where do you meet new words?" leads (onboarding v2 spec §4.5). */
const WAY_FOR: Readonly<Record<Source, WayId>> = {
  books: 'kindle',
  web: 'web',
  video: 'watch',
  class: 'list',
  ai: 'assistants',
};

/**
 * At most this many routes on a notebook with words: the card is a pointer,
 * not a catalogue, and onboarding's plan named the same three.
 */
export const MAX_ROUTES = 3;

/** The routes for a learner who said nothing (onboarding v2's own default). */
export const DEFAULT_ROUTES: readonly WayId[] = ['kindle', 'web', 'assistants'];

/** Every way in, for an empty notebook: the deck import first. */
export const EMPTY_ROUTES: readonly WayId[] = ['import', 'list', 'web', 'assistants'];

/** The ways the card names, in order. Pure, for the card and its tests. */
export function waysFor(words: number, sources: readonly Source[]): WayId[] {
  if (words === 0) return [...EMPTY_ROUTES];
  const picked: WayId[] = [];
  for (const source of sources) {
    const id = WAY_FOR[source];
    if (!picked.includes(id)) picked.push(id);
  }
  return (picked.length > 0 ? picked : [...DEFAULT_ROUTES]).slice(0, MAX_ROUTES);
}

/**
 * The first-five card's rows (uiux 2026-10-26-activation): at most this many
 * on a phone or tablet, one more row on a computer, where nothing is in the
 * way of the screen. One column everywhere (uiux review 27 Oct 2026).
 */
export const FIRST_FIVE_ROWS = 3;
export const FIRST_FIVE_ROWS_DESKTOP = 4;

/** Ways that need a computer: the browser extension and the desktop shortcut. */
const COMPUTER_ONLY: ReadonlySet<WayId> = new Set<WayId>(['web', 'watch']);

/**
 * The ways in for a notebook of one to four words, in order (uiux
 * 2026-10-26-activation). Typing a word is not among them: the hero, the
 * "Met a new word?" row and the + button already offer it. Pasting a text
 * comes first (it needs no file and no other app, and the learner picks
 * every word), then the file import (the Kindle's for somebody who said
 * books), then the places the learner said they meet words, in the order
 * ticked, without the ones this device cannot use. On a computer one more
 * fits, the extension when nothing else is left. Pure, for the card and tests.
 */
export function firstFiveWays(sources: readonly Source[], desktop: boolean): WayId[] {
  const rows: WayId[] = ['paste', sources.includes('books') ? 'kindle' : 'import'];
  const usable = (id: WayId): boolean => desktop || !COMPUTER_ONLY.has(id);
  const answered = sources.map((source) => WAY_FOR[source]).filter((id) => !rows.includes(id) && usable(id));
  const rest: WayId[] = [];
  for (const id of answered) if (!rest.includes(id)) rest.push(id);
  const max = desktop ? FIRST_FIVE_ROWS_DESKTOP : FIRST_FIVE_ROWS;
  const fallback: WayId[] = desktop ? ['assistants', 'web'] : ['assistants'];
  for (const id of fallback) if (!rows.includes(id) && !rest.includes(id)) rest.push(id);
  return [...rows, ...rest].slice(0, max);
}
