/**
 * The mark beside a way in: the product's own logo where the way is another
 * product (the Kindle, the browsers, ChatGPT and Claude), never a stand-in
 * glyph (owner, 2026-10-17). The same files and tile as onboarding's plan,
 * so a learner meets the same picture twice.
 */
import { Icon } from '@/components/ui/Icon.js';
import chromeLogo from '@/features/everywhere/badges/logo-chrome-v1.svg';
import edgeLogo from '@/features/everywhere/badges/logo-edge-v1.svg';
import firefoxLogo from '@/features/everywhere/badges/logo-firefox-v1.svg';
import claudeLogo from '@/features/intro/marks/logo-claude-v1.svg';
import kindleLogo from '@/features/intro/marks/logo-kindle-v1.png';
import openaiLogo from '@/features/intro/marks/logo-openai-v1.svg';
import { cx } from '@/lib/cx.js';
import type { WayId } from './ways.js';
import styles from './WayMark.module.css';

export function WayMark({ way }: { way: WayId }): React.JSX.Element {
  switch (way) {
    case 'kindle':
      return (
        <span className={styles.tile} aria-hidden="true">
          <img className={styles.fill} src={kindleLogo} alt="" width={40} height={40} />
        </span>
      );
    case 'web':
      return (
        <span className={cx(styles.tile, styles.row)} aria-hidden="true">
          <img src={chromeLogo} alt="" width={11} height={11} />
          <img src={edgeLogo} alt="" width={11} height={11} />
          <img src={firefoxLogo} alt="" width={11} height={11} />
        </span>
      );
    case 'assistants':
      return (
        <span className={cx(styles.tile, styles.row)} aria-hidden="true">
          <img src={openaiLogo} alt="" width={16} height={16} />
          <img src={claudeLogo} alt="" width={16} height={16} />
        </span>
      );
    case 'watch':
      return (
        <span className={cx(styles.tile, styles.plain)} aria-hidden="true">
          <Icon name="computer" size={20} weight={1.9} />
        </span>
      );
    case 'list':
      return (
        <span className={cx(styles.tile, styles.plain)} aria-hidden="true">
          <Icon name="list" size={20} weight={1.9} />
        </span>
      );
    case 'paste':
      // The notebook's own "Paste a text" button's icon, so it reads as that button.
      return (
        <span className={cx(styles.tile, styles.plain)} aria-hidden="true">
          <Icon name="note" size={20} weight={1.9} />
        </span>
      );
    case 'import':
      return (
        <span className={cx(styles.tile, styles.plain)} aria-hidden="true">
          <Icon name="notebook" size={20} weight={1.9} />
        </span>
      );
  }
}
