import { useEffect } from 'react';
import { holdSurface, takeEntry, type Surface } from '@/lib/surface.js';

/**
 * Holds a surface while a sheet is open (`lib/surface.ts`): the entry point
 * that opened it (the tab bar's add button, a widget), taken once as it
 * opens, else `fallback`.
 */
export function useSheetSurface(open: boolean, fallback: Surface, entry = true): void {
  useEffect(() => {
    if (!open) return;
    return holdSurface((entry ? takeEntry() : undefined) ?? fallback);
  }, [open, fallback, entry]);
}
