/**
 * The notebook as the list behind Today's focused-practice tiles (owner,
 * 2026-10-17): Starred, Struggling words and Hard spellings each open the
 * notebook filtered to their words, and "Practise these" there starts the
 * same deck the tile does, so Hard spellings still asks for the spelling.
 *
 * Audio only and Confusables are not here: the first is every word, heard
 * rather than read, and the second is pairs, which a list of words is not.
 */
import { FILTERS, type Filter } from './filters.js';

/** The filters that are also a focused-practice deck of the same name. */
export const FOCUS_FILTERS = ['starred', 'struggling', 'tricky'] as const;
export type FocusFilter = (typeof FOCUS_FILTERS)[number];

/** The address parameter that opens the notebook on one filter. */
export const FILTER_PARAM = 'filter';

/**
 * The address parameter that brings the Fill with AI card into view
 * (Today's line about words without a meaning links here).
 */
export const FILL_PARAM = 'fill';

/** Where Today's "Add meanings" leads: the notebook, with Fill with AI in view. */
export const FILL_PATH = `/notebook?${FILL_PARAM}=1`;

export function isFocusFilter(filter: Filter): filter is FocusFilter {
  return (FOCUS_FILTERS as readonly Filter[]).includes(filter);
}

/** A filter named in the address, or undefined for anything that is not one. */
export function filterFromParam(value: string | null): Filter | undefined {
  return value !== null && (FILTERS as readonly string[]).includes(value) ? (value as Filter) : undefined;
}

/** Where a focused-practice tile's list lives. */
export function focusListPath(filter: FocusFilter): string {
  return `/notebook?${FILTER_PARAM}=${filter}`;
}

/** What the notebook's list is cut down by, as "Practise these" needs to know it. */
export interface PractiseView {
  filter: Filter;
  /** The settled search text. */
  query: string;
  topic: string | undefined;
  level: string | undefined;
  kind: string | undefined;
  /** Every notebook is in view, not only the one being shown. */
  across: boolean;
}

/**
 * Where "Practise these" goes. A list that is exactly one focused deck
 * (one of those filters and nothing else) starts that deck, as its tile on
 * Today does, so Hard spellings asks for spellings and the session's own
 * rules pick and cap the words. Anything else is a session over exactly
 * the words on the page, in notebook order.
 */
export function practisePath(view: PractiseView, ids: readonly string[]): string {
  const onlyTheDeck =
    isFocusFilter(view.filter) &&
    view.query.trim() === '' &&
    view.topic === undefined &&
    view.level === undefined &&
    view.kind === undefined;
  if (onlyTheDeck) {
    const query = new URLSearchParams({ deck: view.filter });
    if (view.across) query.set('scope', 'all');
    return `/session?${query.toString()}`;
  }
  return `/session?deck=group&ids=${ids.join(',')}`;
}
